import importlib
spec = {
 "netsim.container": {"DockerHost": ["image","cpu_shares","cpu_quota","cpu_period","mem_limit_mb",
                                     "STARTUP_OVERHEAD_MS","HOST_STARTUP_MS","cpu_fraction",
                                     "startup_time_ms","is_container"]},
 "netsim.sfc": {"VNF": ["name","processing_delay_ms","overhead_pct","throughput_factor"],
                "ServiceFunctionChain": ["num_links","compute_throughput","compute_latency"]},
 "netsim.containernet": {"Containernet": ["addDocker","compute_resource_fairness","total_nodes",
                                          "startup_overhead_ratio"]},
}
inst = {"DockerHost": lambda c: c("n"), "VNF": lambda c: c("v"),
        "ServiceFunctionChain": lambda c: c(), "Containernet": lambda c: c()}
bad = []
for mod, classes in spec.items():
    m = importlib.import_module(mod)
    for cname, names in classes.items():
        if not hasattr(m, cname):
            bad.append(f"MISSING class {mod}.{cname}"); continue
        cls = getattr(m, cname)
        obj = inst[cname](cls)
        for n in names:
            if not hasattr(obj, n):
                bad.append(f"MISSING {cname}.{n}")
            else:
                print(f"OK {mod}.{cname}.{n} = {getattr(obj,n)!r}"[:110])
print("\nPROBLEMS:", bad or "none")
EOF
